'use strict';
const intakeBaseAction=action,intakeBaseClose=closeModal;
Object.assign(app,{intakeJob:null,pdfQueue:Promise.resolve(),pdfRevision:0});
function receiptLinks(t){return (t.document_ids||[]).map(id=>{const d=app.data.documents.find(x=>x.id===id);return d?`<button type="button" class="text-link" data-action="open-document" data-id="${id}">${esc(d.title)}</button>`:'';}).join(' · ');}
function evidenceForm(id,none=false){const t=app.data.transactions.find(t=>t.id===id);if(!t)return toast('Zahlung nicht gefunden.',true);app.transactionReceiptFile=null;app.recoveredReceiptFile=null;
 showModal('Beleg & Einordnung',`<form id="evidence-form" data-id="${id}"><div class="modal-body"><div class="form-result" role="alert"></div><div class="evidence-intro"><div><strong>${esc(t.partner)}</strong><p>${esc(t.title)}</p><span class="small muted">${fmtDate(t.paid_on)} · ${esc(t.payment_method==='cash'?'Bar bezahlt':accountName(t.account_id))}</span></div><strong>${t.direction==='income'?'+':'−'} ${money(t.amount_cents)}</strong></div><div class="field-row">${select('Bereich','scope',Object.entries(scopeNames),t.scope||'unknown')}${select('Kategorie (vorläufig)','category',categories,t.category||'Unsortiert')}</div><div class="file-picker receipt-picker"><label for="transaction-receipt-file">PDF / Beleg hier hochladen (optional)</label><input id="transaction-receipt-file" type="file" accept=".pdf,.jpg,.jpeg,.png,.txt,.csv,.xml"><p id="transaction-receipt-label" class="small muted">Das Original wird mit genau dieser Zahlung verbunden.</p></div>${select('Wenn kein Beleg vorliegt','receipt_state',[['pending','Später ergänzen'],['none','Kein Beleg vorhanden']],none?'none':t.receipt_state||'pending')}${textarea('Notiz zum Beleg / Verwendungszweck','receipt_note',t.receipt_note||'','maxlength="2000" placeholder="z. B. private Einzahlung aus Ersparnissen oder Zutaten für Video …"')}<details class="document-link-details"><summary>Vorhandene Belege zuordnen${t.document_ids.length?' · '+t.document_ids.length:''}</summary>${receiptLinks(t)}<label>Dokumente<select name="document_ids" multiple size="4">${app.data.documents.filter(d=>d.kind!=='Kontoauszug'||t.document_ids.includes(d.id)).map(d=>`<option value="${d.id}"${t.document_ids.includes(d.id)?' selected':''}>${d.year} · ${esc(d.title)}</option>`).join('')}</select></label></details>${t.bank_import_id?`<p>${button('Original-Kontoauszug','bank-original','file','small',`data-id="${t.bank_import_id}"`)}</p>`:''}<p class="small muted section-gap">Privat braucht keinen Betriebsrechnungsbeleg. „Kein Beleg“ bei betrieblichen Zahlungen hält die Prüfung offen. Ein Kontoauszug ersetzt keine erforderliche Rechnung.</p></div><div class="modal-footer"><button type="submit" class="btn primary">Bei dieser Zahlung speichern</button></div></form>`);addSaveState($('#evidence-form'));if(none){app.draftRevision++;queueDraft($('#evidence-form'));}
}
async function openIntakeJob(id){const j=await api('/api/intake/job?id='+encodeURIComponent(id));app.intakeJob=j;if(j.kind==='pdf'&&j.state==='complete'&&j.approvals?.length)return pdfReviewForm(j);if(j.import_id&&j.kind==='pdf')return showBankPreview(await api('/api/banking/preview?id='+j.import_id));if(j.kind==='classify')return showBankPreview(await api('/api/banking/preview?id='+j.import_id));
 if(['review','error'].includes(j.state)&&j.pages.length)return pdfReviewForm(j);
 showModal('PDF-Auszug lesen',`<div class="modal-body" id="pdf-job" data-id="${j.id}"><span class="tag green">Original gespeichert</span><h3 class="section-gap">${esc(app.data.documents.find(d=>d.id===j.document_id)?.title||'Kontoauszug')}</h3><p class="small muted">${esc(accountName(j.account_id))} · ${j.year}</p><p id="pdf-progress" class="section-gap" role="status">${esc(j.error||j.progress||'Bereit zum Lesen.')}</p><p class="small muted section-gap">Nach dem Lesen prüfst du die Zahlungen übersichtlich nach Monaten. Erkannte Volksbank-Tabellen werden direkt gelesen; bei anderen Layouts helfen deine lokalen KIs. Das kann einige Minuten dauern. Du darfst dieses Fenster schließen.</p>${j.error_code==='pdf_password'?'<label class="field">PDF-Öffnungskennwort<input id="pdf-password" type="password" autocomplete="off"><span class="small muted">Nur für diesen Leseversuch. Wird nicht gespeichert oder an die KI weitergegeben.</span></label>':''}<div class="actions section-gap">${button(j.state==='error'?'Erneut lesen':'Zahlungen lesen','start-pdf','spark','primary',`data-id="${j.id}"${['running','queued'].includes(j.state)?' disabled':''}`)}${button('Original öffnen','pdf-original','file','',`data-id="${j.document_id}"`)}${button('In Papierkorb','trash-upload','','ghost',`data-job-id="${j.id}"`)}</div><details class="source-details"><summary>PDF-Unterstützung einrichten</summary><p class="small">EINRICHTEN_WINDOWS.bat einmal ausführen. Bei eingescannten Seiten zusätzlich OCR_EINRICHTEN_WINDOWS.bat. Für KI-Vorschläge und andere PDF-Layouts muss Ollama laufen; die drei Modelle unter Einstellungen auswählen.</p></details></div>`);
 if(['running','queued'].includes(j.state))pollIntake(j.id,'pdf');
}
async function startPdfJob(id,useAI=true){const password=$('#pdf-password')?.value||'';if($('#pdf-password'))$('#pdf-password').value='';const r=await api('/api/intake/start',{job_id:id,password,use_ai:useAI});const el=$('#pdf-progress');if(el)el.textContent='Auswertung startet …';const b=$('[data-action=start-pdf]');if(b)b.disabled=true;return pollIntake(r.id,'pdf');}
async function pollIntake(id,kind){clearTimeout(app.intakePoll);const j=await api('/api/intake/job?id='+id);if(kind==='pdf')app.intakeJob=j;const label=kind==='pdf'?($('#pdf-job')?.dataset.id===id?$('#pdf-progress'):null):($('#bank-commit-form')?.dataset.id===j.import_id?$('#import-ai-status'):null);if(label)label.textContent=j.error||j.progress;
 if(['queued','running'].includes(j.state)){app.intakePoll=setTimeout(()=>pollIntake(id,kind).catch(e=>toast(e.message,true)),2500);return;}
 app.bankYear=null;if(kind==='pdf'){if($('#pdf-job')?.dataset.id===id)await openIntakeJob(id);else toast(j.state==='error'?'PDF benötigt Prüfung. Unter Kontoauszüge fortsetzen.':'PDF gelesen. Unter Kontoauszüge prüfen.',j.state==='error');}
 else if($('#bank-commit-form')?.dataset.id===j.import_id){if(j.state==='complete'){if(label)label.innerHTML='Drei KI-Perspektiven gespeichert. '+button('Vorschläge ansehen','resume-import','arrow','small',`data-id="${j.import_id}"`); }else if(label)label.textContent='Vorschau bleibt gespeichert. '+(j.error||j.progress);}
 if(app.view==='banking')loadBank().catch(e=>toast(e.message,true));
}
function pdfMonth(day){return /^\d{4}-\d{2}-\d{2}$/.test(day||'')?day.slice(0,7):'unknown';}
function pdfMonthLabel(key){return key==='unknown'?'Datum noch prüfen':(months[Number(key.slice(5))-1]||'Monat prüfen')+' '+key.slice(0,4);}
function pdfGroupMarkup(rows,renderRow){const groups=new Map();rows.forEach((row,i)=>{const key=pdfMonth(row.booked_on);if(!groups.has(key))groups.set(key,[]);groups.get(key).push({row,i});});return [...groups].sort((a,b)=>a[0].localeCompare(b[0])).map(([key,items])=>`<section class="pdf-month" data-month="${esc(key)}"><header class="pdf-month-head"><h3>${esc(pdfMonthLabel(key))}</h3><span class="pdf-month-totals small muted"></span></header>${items.sort((a,b)=>(a.row.booked_on||'').localeCompare(b.row.booked_on||'')||a.i-b.i).map(({row,i})=>renderRow(row,i)).join('')}</section>`).join('');}
function pdfAmount(value){const text=String(value??'').trim().replace('−','-'),m=text.match(/^([+-]?)(\d{1,3}(?:\.\d{3})+|\d+)(?:,(\d{1,2}))?$/);if(!m)return null;const c=(Number(m[2].replaceAll('.',''))*100+Number((m[3]||'').padEnd(2,'0')))*(m[1]==='-'?-1:1);return Number.isSafeInteger(c)?c:null;}
function pdfDate(value){try{return fmtDate(value);}catch{return 'Datum prüfen';}}
function pdfRowMarkup(row,index,pages){const amount=pdfAmount(row.amount),scope=row.scope||'unknown',reviewed=!!row.reviewed,outside=row.booked_on&&row.booked_on.slice(0,4)!==String(app.intakeJob.year);
 return `<article class="pdf-row pdf-payment${row.proof_error?' has-proof-error':''}" data-index="${index}" data-scope="${esc(scope)}" data-reviewed="${reviewed?'1':'0'}" data-choice="${esc(row.choice||'')}" data-excluded="${row.excluded?'1':'0'}" data-exclusion-reason="${esc(row.exclusion_reason||'')}"><div class="pdf-payment-main"><time class="pdf-date">${row.booked_on?esc(pdfDate(row.booked_on)):'Datum prüfen'}</time><div class="pdf-recipient"><strong class="pdf-partner">${esc(row.partner||'Empfänger prüfen')}</strong><p class="pdf-purpose" title="${esc(row.purpose||'')}">${esc(row.purpose||'Zweck prüfen')}</p><span class="pdf-row-state small muted">${outside?'Anderes Arbeitsjahr · wird ausgelassen':reviewed?'Einordnung gewählt':row.proof_error?'Originalstelle prüfen':row.suggestion?'KI-Vorschlag · bitte bestätigen':'Einordnung wählen'}</span></div><strong class="pdf-amount">${amount===null?'Betrag prüfen':money(amount)}</strong><div class="pdf-scope-picker" role="group" aria-label="Einordnung Zahlung ${index+1}">${[['private','Privat'],['business','Betrieblich']].map(([value,label])=>`<button type="button" data-action="pdf-scope" data-value="${value}" aria-pressed="${reviewed&&scope===value}"${outside?' disabled':''}>${label}</button>`).join('')}<label class="pdf-more-scope"><span class="sr-only">Weitere Einordnung Zahlung ${index+1}</span><select data-pdf-more-scope aria-label="Weitere Einordnung Zahlung ${index+1}"${outside?' disabled':''}>${options([['','Mehr …'],['mixed','Gemischt'],['unknown','Später klären'],['transfer','Eigener Übertrag']],reviewed&&['mixed','unknown','transfer'].includes(scope)?scope:'')}</select></label></div></div>
 <section class="pdf-row-diagnosis" hidden aria-label="Abgleich mit Original"></section><div class="pdf-row-actions"><details class="pdf-exclude-menu"><summary>Auslassen</summary><p class="small muted">Warum soll diese Zeile nicht ins Dashboard?</p>${button('Schon erfasst / doppelt','exclude-pdf-row','','small','data-reason="already_recorded"')}${button('Keine eigene Zahlung','exclude-pdf-row','','small','data-reason="not_payment"')}<p class="small muted">„Keine eigene Zahlung“ z. B. für die Aufschlüsselung einer bereits enthaltenen Gebühr.</p></details>${button('Wieder aufnehmen','restore-pdf-row','','ghost small')}</div><details class="pdf-row-details"><summary>Details & Notiz${row.proof_error?' · Textstelle prüfen':''}</summary>${row.proof_error?`<p class="form-error">${esc(row.proof_error)}</p>`:''}${row.suggestion?`<p class="small muted">KI-Vorschlag: ${esc(scopeNames[scope])}. ${esc(row.suggestion)}</p>`:''}<div class="field-row"><label>Datum der Zahlung<input data-key="booked_on" type="date" value="${esc(row.booked_on||'')}" required></label><label>Betrag · Minus bedeutet Auszahlung<input data-key="amount" value="${esc(row.amount||'')}" inputmode="decimal" required></label></div><div class="field-row"><label>Empfänger / Absender<input data-key="partner" maxlength="200" value="${esc(row.partner||'')}" required></label><label>Verwendungszweck<input data-key="purpose" maxlength="1000" value="${esc(row.purpose||'')}" required></label></div><label>Deine Notiz (optional)<textarea data-key="review_note" rows="2" maxlength="2000" placeholder="z. B. Einkauf für mein Video oder private Ersparnisse">${esc(row.review_note||'')}</textarea></label><input type="hidden" data-key="currency" value="${esc(row.currency||'EUR')}"><input type="hidden" data-key="source_id" value="${esc(row.source_id||'')}"><input type="hidden" data-key="category" value="${esc(row.category||'Unsortiert')}"><details class="source-details"><summary>Originalstelle · Seite ${Number(row.page)||1}</summary><label>Seite<select data-key="page">${options(pages.map(p=>[p.page,'Seite '+p.page]),row.page||pages[0]?.page)}</select></label><label>Textstelle aus dem Auszug<textarea data-key="quote" rows="3" maxlength="4000" required>${esc(row.quote||'')}</textarea></label>${row.ai?`<p class="small muted">Arbeiter: ${esc(row.ai.worker.reason)}<br>Prüfer: ${esc(row.ai.reviewer.reason)}</p>`:''}</details></details></article>`;
}
function pdfReviewForm(j){app.intakeJob=j;app.pdfReconciliation=null;app.pdfOverrides=structuredClone(j.result.month_overrides||{});const r=j.result,rows=r.rows||[],incomplete=r.all_pages_read===false||j.state==='error';
 showModal('Deine Zahlungen prüfen',`<form id="pdf-review-form" data-id="${j.id}" novalidate><div class="modal-body pdf-review-screen"><div class="pdf-review-intro"><div><span class="tag">Monate prüfen & übernehmen</span><p class="small muted section-gap">${esc(accountName(j.account_id))} · Arbeitsjahr ${j.year}</p></div>${button('Original öffnen','pdf-original','file','small',`data-id="${j.document_id}"`)}</div><p class="pdf-review-help">Wähle je Zahlung <strong>Privat</strong> oder <strong>Betrieblich</strong>. Unter „Auslassen“ entfernst du falsche oder bereits erfasste Zeilen aus der Auswahl.</p><div class="pdf-summary-strip"><div><span>Zur Übernahme</span><strong id="pdf-count">–</strong></div><div><span>Geldeingänge</span><strong id="pdf-income">–</strong></div><div><span>Geldausgänge</span><strong id="pdf-expense">–</strong></div></div><p class="save-state" role="status">Auszug gespeichert. Deine Einordnung wird automatisch gesichert.</p>
 ${incomplete||!rows.length?`<div class="pdf-read-alert"><strong>${rows.length?'Lesen noch nicht abgeschlossen':'Noch keine verlässliche Zahlungsliste'}</strong><p>${esc(j.error||'Ein Teil des Auszugs konnte nicht vollständig gelesen werden. Das bedeutet nicht, dass keine Zahlungen vorhanden sind.')}</p>${button('Erneut lesen lassen','retry-pdf','spark','small',`data-id="${j.id}"`)}</div>`:''}
 <p id="pdf-review-status" class="small muted" role="status">Kontrollwerte werden abgeglichen …</p><details id="pdf-approved-summary" class="pdf-approved-summary" hidden><summary></summary><div class="approved-month-list"></div></details><div id="pdf-approved-rows" hidden inert></div><div id="pdf-rows">${pdfGroupMarkup(rows,(row,i)=>pdfRowMarkup(row,i,j.pages))}</div>
 <details id="pdf-excluded" class="pdf-excluded" hidden><summary><span id="pdf-excluded-count"></span> ausgelassen · ansehen / rückgängig</summary><p class="small muted">Diese Zeilen werden nicht neu übernommen. Dein Original bleibt unverändert.</p><div id="pdf-excluded-rows"></div></details><div class="pdf-secondary-actions">${button('Fehler prüfen','check-pdf-rows','','small')}${button('Fehlende Zahlung ergänzen','add-pdf-row','plus','ghost small')}${!incomplete&&rows.length&&!j.approvals?.length?button('Erneut lesen','retry-pdf','','ghost small',`data-id="${j.id}"`):''}</div>
 <details class="source-details pdf-technical"><summary>Kontostand & Originaltext bei Bedarf ansehen</summary><p class="small muted">Anfangsstand + Eingänge − Ausgänge = Endstand. Das sind Kontobewegungen, keine fertige EÜR.</p><div class="field-row">${field('Anfangsstand (optional)','opening_balance',r.opening_balance??(r.opening_cents==null?'':moneyInput(r.opening_cents)))}${field('Endstand (optional)','closing_balance',r.closing_balance??(r.closing_cents==null?'':moneyInput(r.closing_cents)))}</div>${textarea('Originalstelle für geänderte Kontostände','balance_quote',r.balance_quote||'','maxlength="4000"')}${j.pages.map(p=>`<details class="source-details"><summary>Seite ${p.page}${r.page_status?.find(s=>s.page===p.page)?.state==='notes'?' · Hinweise der Bank':''}</summary><pre class="pdf-source-text">${esc(p.text)}</pre></details>`).join('')}</details>
 <details class="source-details"><summary>Allgemeine Notiz zur Prüfung</summary>${textarea('Wie hast du offene Punkte geklärt?','review_note',r.review_note||'','maxlength="2000"')}</details>
 <p class="small muted">Belege kannst du nach der Freigabe ergänzen. „Betrieblich“ bestätigt noch keinen steuerlichen Abzug.</p></div><div class="modal-footer pdf-review-footer"><div class="form-result" role="alert" tabindex="-1"></div><label class="check pdf-approval"><input name="checked" type="checkbox">Ausgewählte Monate und Einordnung am Original geprüft.</label><div class="pdf-submit-row"><span id="pdf-selection-status" role="status"></span><button class="btn primary" type="submit">Alle offenen Monate freigeben</button></div></div></form>`);
 const form=$('#pdf-review-form');form.addEventListener('input',e=>{if(e.target.matches('[data-key]')){const row=e.target.closest('.pdf-row');if(row?.dataset.diagnosed==='1')$('.pdf-row-diagnosis',row).classList.add('is-outdated');}updatePdfSummary(form);schedulePdfSave(form);});form.addEventListener('change',e=>{if(e.target.matches('[data-key=booked_on]'))regroupPdfRows(form);});regroupPdfRows(form);refreshPdfReconciliation(form);
}
function collectPdf(form){return {id:form.dataset.id,rows:[...form.querySelectorAll('.pdf-row')].sort((a,b)=>Number(a.dataset.index)-Number(b.dataset.index)).map(row=>{const value={scope:row.dataset.scope||'unknown',reviewed:row.dataset.reviewed==='1',excluded:row.dataset.excluded==='1',exclusion_reason:row.dataset.exclusionReason||'',choice:row.dataset.choice||''};for(const input of row.querySelectorAll('[data-key]'))value[input.dataset.key]=input.dataset.key==='page'?Number(input.value):input.value;return value;}),overrides:app.pdfOverrides||{},review_note:$('[name=review_note]',form).value,opening_balance:$('[name=opening_balance]',form).value,closing_balance:$('[name=closing_balance]',form).value,balance_quote:$('[name=balance_quote]',form).value};}
function updatePdfSummary(form){let incoming=0,outgoing=0,open=0,count=0,excludedCount=0;for(const row of form.querySelectorAll('.pdf-row')){if(row.dataset.approved==='1')continue;const amount=pdfAmount($('[data-key=amount]',row).value),day=$('[data-key=booked_on]',row).value,excluded=row.dataset.excluded==='1',eligible=day.slice(0,4)===String(app.intakeJob.year);if(excluded)excludedCount++;if(!excluded&&eligible){count++;if(amount!==null){if(amount>0)incoming+=amount;else outgoing-=amount;}if(row.dataset.reviewed!=='1')open++;}$('.pdf-amount',row).textContent=amount===null?'Betrag prüfen':money(amount);$('.pdf-date',row).textContent=day?pdfDate(day):'Datum prüfen';$('.pdf-partner',row).textContent=$('[data-key=partner]',row).value||'Empfänger prüfen';$('.pdf-purpose',row).textContent=$('[data-key=purpose]',row).value||'Zweck prüfen';$('.pdf-row-state',row).textContent=excluded?(row.dataset.exclusionReason==='not_payment'?'Ausgelassen · keine eigene Zahlung':'Ausgelassen · schon erfasst'):!day?'Datum prüfen':!eligible?'Anderes Arbeitsjahr · wird ausgelassen':row.dataset.reviewed==='1'?scopeNames[row.dataset.scope]+' · gewählt':'Einordnung wählen';row.classList.toggle('is-reviewed',!excluded&&row.dataset.reviewed==='1');row.classList.toggle('is-excluded',excluded);row.querySelectorAll('[data-action=pdf-scope]').forEach(b=>{b.setAttribute('aria-pressed',row.dataset.reviewed==='1'&&row.dataset.scope===b.dataset.value?'true':'false');b.disabled=!eligible||excluded;});}
 $('#pdf-count',form).textContent=count;$('#pdf-income',form).textContent=money(incoming);$('#pdf-expense',form).textContent=money(outgoing);$('#pdf-selection-status',form).textContent=open?`${open} ${open===1?'Einordnung fehlt':'Einordnungen fehlen'}`:count?'Einordnungen gewählt':'Keine neue Zahlung ausgewählt';$('#pdf-excluded-count',form).textContent=excludedCount;$('#pdf-excluded',form).hidden=!excludedCount;for(const group of form.querySelectorAll('.pdf-month')){const count=group.querySelectorAll('.pdf-row').length;$('.pdf-month-totals',group).textContent=count+' '+(count===1?'Zahlung':'Zahlungen');}}
function pdfFocus(input){let parent=input.parentElement;while(parent){if(parent.tagName==='DETAILS')parent.open=true;parent=parent.parentElement;}input.scrollIntoView({block:'center'});input.focus();}
function validatePdfForm(form){const j=app.intakeJob;if(j.result.all_pages_read===false||j.state==='error')throw new Error('Noch nicht alle Seiten sind gelesen. Bitte „Erneut lesen“ auswählen.');if(!form.querySelector('.pdf-row'))throw new Error('Noch keine Zahlungen vorhanden. Bitte erneut lesen oder eine Zahlung ergänzen.');for(const row of form.querySelectorAll('.pdf-row')){if(row.dataset.excluded==='1'&&row.dataset.exclusionReason==='not_payment')continue;for(const key of ['booked_on','amount','partner','purpose','quote']){const input=$('[data-key='+key+']',row);if(!input.value.trim()||!input.checkValidity()||key==='amount'&&(pdfAmount(input.value)===null||pdfAmount(input.value)===0)){pdfFocus(input);throw new Error('Bitte das markierte Feld dieser Zahlung prüfen: '+({booked_on:'Datum',amount:'Betrag',partner:'Empfänger / Absender',purpose:'Verwendungszweck',quote:'Originalstelle'}[key])+'.');}}if(row.dataset.excluded!=='1'&&$('[data-key=booked_on]',row).value.slice(0,4)===String(j.year)&&row.dataset.reviewed!=='1'){pdfFocus($('[data-action=pdf-scope]',row));throw new Error('Bitte jede Zahlung einordnen: Privat, Betrieblich oder unter „Mehr“ später klären.');}}if(!$('[name=checked]',form).checked){pdfFocus($('[name=checked]',form));throw new Error('Bitte unten „Zahlungen und Auswahl am Original geprüft“ bestätigen.');}}
function clearPdfDiagnostics(form){for(const row of form.querySelectorAll('.pdf-row')){delete row.dataset.diagnosed;const box=$('.pdf-row-diagnosis',row);box.hidden=true;box.innerHTML='';box.classList.remove('is-outdated');}app.pdfDiagnostics=[];const result=$('.form-result',form);if(result?.dataset.pdfDiagnostics==='1'){result.textContent='';result.className='form-result';delete result.dataset.pdfDiagnostics;}}
function showPdfDiagnostics(form,details,focus=true){clearPdfDiagnostics(form);app.pdfDiagnostics=details.diagnostics||[];const ordered=[...form.querySelectorAll('.pdf-row')].sort((a,b)=>Number(a.dataset.index)-Number(b.dataset.index));for(const d of app.pdfDiagnostics){const row=ordered[d.index];if(!row)continue;row.dataset.diagnosed='1';const box=$('.pdf-row-diagnosis',row);box.hidden=false;box.innerHTML=`<div class="pdf-diagnosis-heading"><strong>Diese Zahlung braucht einen Abgleich</strong><span class="tag">PDF-Seite ${esc(d.page)}</span></div><p>${esc(d.explanation)}</p><p class="pdf-diagnosis-stale">Du hast Angaben geändert. Bitte „Fehler prüfen“ erneut wählen.</p>${d.candidates.map((c,i)=>`<div class="pdf-source-candidate"><strong>${d.candidates.length>1?'Mögliche Originalzeile '+(i+1):'Originalzeile zum Vergleichen'} · ${esc(c.partner)}</strong><div class="pdf-compare-wrap"><table class="pdf-compare"><thead><tr><th>Feld</th><th>Deine Eingabe</th><th>Original</th></tr></thead><tbody>${[['Datum',pdfDate(d.entered.booked_on),pdfDate(c.booked_on),'booked_on'],['Betrag',d.entered.amount+' €',money(c.amount_cents),'amount'],['PDF-Seite',d.page,c.page,'page']].map(([label,before,after,key])=>`<tr${c.differences.includes(key)?' class="is-different"':''}><th>${label}</th><td>${esc(before)}</td><td>${esc(after)}</td></tr>`).join('')}</tbody></table></div>${c.explanation!==d.explanation?`<p class="small">${esc(c.explanation)}</p>`:''}${c.already_used?'<p class="small error-text">Diese Originalzeile ist schon einer anderen Zahlung zugeordnet. Prüfe, ob eine Zeile doppelt gelesen wurde oder eine andere Originalstelle gemeint ist.</p>':''}<p class="small muted">${esc(c.purpose)} · ${c.amount_cents<0?'Auszahlung (S / Minus)':'Eingang (H / Plus)'}</p><details class="source-details"><summary>Originaltext dieser Zeile ansehen</summary><pre class="pdf-source-text">${esc(c.quote)}</pre></details>${button('Diese Originalzeile übernehmen','apply-pdf-source','','small',`data-diagnostic="${d.index}" data-candidate="${i}"`)}</div>`).join('')}${d.candidate_count>d.candidates.length?'<p class="small muted">Weitere ähnliche Zeilen vorhanden. Bitte auch den Originalauszug vergleichen.</p>':''}<div class="actions">${button('Angaben selbst bearbeiten','edit-pdf-source','','ghost small')}${button('PDF öffnen','pdf-original','file','ghost small',`data-id="${app.intakeJob.document_id}"`)}</div><details class="source-details"><summary>Technischer Hinweis</summary><p class="small muted">${esc(d.message)}</p></details>`;}
 const result=$('.form-result',form);result.className='form-result form-error';result.dataset.pdfDiagnostics='1';result.innerHTML=`${app.pdfDiagnostics.length} ${app.pdfDiagnostics.length===1?'Zahlung braucht':'Zahlungen brauchen'} einen Abgleich mit dem Original. ${button('Zur ersten Zahlung','first-pdf-problem','','ghost small')}`;if(focus)jumpPdfProblem(form);}
function jumpPdfProblem(form){const row=form.querySelector('[data-diagnosed="1"]');if(!row)return;const box=$('.pdf-row-diagnosis',row);box.tabIndex=-1;box.focus({preventScroll:true});box.scrollIntoView({block:'start'});}
async function checkPdfRows(form){const btn=$('[data-action=check-pdf-rows]',form),result=$('.form-result',form);btn.disabled=true;form.inert=true;try{await queuePdfSave(form);const r=await api('/api/intake/pdf-check',collectPdf(form));clearPdfDiagnostics(form);result.className='form-result';result.textContent=r.message;toast('Originalzuordnung geprüft.');}catch(e){form.inert=false;if(e.details?.kind==='pdf_rows')showPdfDiagnostics(form,e.details);else{result.className='form-result form-error';result.textContent=e.message;}}finally{btn.disabled=false;form.inert=false;}}
function setPdfScope(row,value){row.dataset.scope=value;row.dataset.reviewed='1';$('[data-pdf-more-scope]',row).value=['private','business'].includes(value)?'':value;const form=row.closest('form');updatePdfSummary(form);schedulePdfSave(form);}
function schedulePdfSave(form){app.unsavedDraft=true;markPdfChecksStale(form);app.pdfRevision++;clearTimeout(app.pdfSaveTimer);app.pdfSaveTimer=setTimeout(()=>queuePdfSave(form).catch(()=>{}),600);}
function queuePdfSave(form){if(!form)return Promise.resolve();clearTimeout(app.pdfSaveTimer);const data=collectPdf(form),label=$('.save-state',form),revision=app.pdfRevision;label.textContent='Änderungen werden gespeichert …';app.pdfQueue=app.pdfQueue.catch(()=>{}).then(()=>api('/api/intake/pdf-review',data)).then(()=>{label.textContent='Änderungen gespeichert · '+new Date().toLocaleTimeString('de-DE');if(revision===app.pdfRevision){app.unsavedDraft=false;schedulePdfReconciliation(form);}}).catch(e=>{label.textContent='Nicht gespeichert: '+e.message;app.unsavedDraft=true;throw e;});return app.pdfQueue;}
closeModal=function(){const pdf=$('#pdf-review-form');if(pdf&&!app.suppressDraft)queuePdfSave(pdf).catch(e=>toast(e.message,true));intakeBaseClose();};
$('#modal').addEventListener('cancel',()=>{const f=$('#pdf-review-form');if(f)queuePdfSave(f).catch(e=>toast(e.message,true));});
action=async function(name,el){switch(name){
 case 'check-pdf-rows':return refreshPdfReconciliation(el.closest('form'),true);
 case 'first-pdf-problem':return jumpPdfProblem(el.closest('form'));
 case 'edit-pdf-source':{const row=el.closest('.pdf-row');return pdfFocus($('[data-key=booked_on]',row));}
 case 'apply-pdf-source':{const form=el.closest('form'),d=app.pdfDiagnostics.find(x=>x.index===Number(el.dataset.diagnostic)),candidate=d?.candidates[Number(el.dataset.candidate)];if(!candidate)throw new Error('Bitte die Fehlerprüfung erneut starten.');const row=el.closest('.pdf-row');const changed=$('[data-key=booked_on]',row).value!==candidate.booked_on||pdfAmount($('[data-key=amount]',row).value)!==candidate.amount_cents;for(const key of ['page','booked_on','amount','quote','source_id','currency','partner','purpose']){const control=$('[data-key='+key+']',row);if(control)control.value=candidate[key]??'';}if(changed)row.dataset.reviewed='0';row.dataset.choice='';delete row.dataset.diagnosed;$('.pdf-row-diagnosis',row).hidden=true;regroupPdfRows(form);schedulePdfSave(form);$('[name=checked]',form).checked=false;const result=$('.form-result',form);result.className='form-result';result.textContent='Originalzeile übernommen. '+(changed?'Bitte die Einordnung dieser Zahlung erneut wählen. ':'')+'Anschließend erneut prüfen oder freigeben.';row.scrollIntoView({block:'center'});return;}
 case 'pdf-scope':return setPdfScope(el.closest('.pdf-row'),el.dataset.value);
 case 'retry-pdf':{const form=$('#pdf-review-form');await queuePdfSave(form);app.suppressDraft=true;closeModal();app.suppressDraft=false;await startPdfJob(el.dataset.id);return openIntakeJob(el.dataset.id);}
 case 'intake-job':return openIntakeJob(el.dataset.id);
 case 'start-pdf':return startPdfJob(el.dataset.id);
 case 'pdf-original':return download(`/api/documents/${el.dataset.id}/file`,'Kontoauszug.pdf');
 case 'evidence':return evidenceForm(el.dataset.id);
 case 'no-evidence':return evidenceForm(el.dataset.id,true);
 case 'add-pdf-row':{const form=$('#pdf-review-form');$('#pdf-rows').insertAdjacentHTML('beforeend',pdfRowMarkup({page:app.intakeJob.pages[0]?.page},Math.max(-1,...[...form.querySelectorAll('.pdf-row')].map(r=>Number(r.dataset.index)))+1,app.intakeJob.pages));regroupPdfRows(form);updatePdfSummary(form);schedulePdfSave(form);return;}
 case 'exclude-pdf-row':case 'restore-pdf-row':{const row=el.closest('.pdf-row'),form=row.closest('form');row.dataset.excluded=name==='exclude-pdf-row'?'1':'0';row.dataset.exclusionReason=name==='exclude-pdf-row'?el.dataset.reason:'';if(name==='restore-pdf-row'&&row.dataset.choice==='skip')row.dataset.choice='';$('.pdf-exclude-menu',row).open=false;regroupPdfRows(form);schedulePdfSave(form);if(name==='exclude-pdf-row')toast('Zeile ausgelassen. Unter „Ausgelassen“ kannst du sie wieder aufnehmen.');return;}
 case 'reopen-pdf-review':{await app.reviewQueue;const j=await api('/api/intake/pdf-reopen',{import_id:el.dataset.id});return pdfReviewForm(j);}
 default:return intakeBaseAction(name,el);}};
const intakeBaseSubmit=submit;
submit=async function(form){if(form.id!=='pdf-review-form')return intakeBaseSubmit(form);return approvePdfMonths(form);};
document.addEventListener('change',e=>{if(e.target.matches('[data-pdf-more-scope]')&&e.target.value)setPdfScope(e.target.closest('.pdf-row'),e.target.value);});

function regroupPdfRows(form){
 const container=$('#pdf-rows',form),excluded=$('#pdf-excluded-rows',form),frozen=$('#pdf-approved-rows',form),rows=[...form.querySelectorAll('.pdf-row')],groups=new Map(),approved=new Set((app.intakeJob.approvals||[]).flatMap(a=>a.rows.map(r=>r.index)));
 for(const row of rows){if(approved.has(Number(row.dataset.index))){row.dataset.approved='1';frozen.append(row);continue;}if(row.dataset.excluded==='1'){excluded.append(row);const key=pdfMonth($('[data-key=booked_on]',row).value);if(!groups.has(key))groups.set(key,[]);continue;}const key=pdfMonth($('[data-key=booked_on]',row).value);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(row);}
 const blocks=[];for(const [key,items] of [...groups].sort((a,b)=>a[0].localeCompare(b[0]))){const section=document.createElement('section');section.className='pdf-month';section.dataset.month=key;section.innerHTML=`<header class="pdf-month-head"><div><h3>${esc(pdfMonthLabel(key))}</h3><span class="pdf-month-totals small muted"></span></div><span class="pdf-month-status tag">Prüfung wird geladen</span></header><div class="pdf-month-check"></div>`;for(const row of items.sort((a,b)=>$('[data-key=booked_on]',a).value.localeCompare($('[data-key=booked_on]',b).value)))section.append(row);blocks.push(section);}container.replaceChildren(...blocks);updatePdfSummary(form);if(app.pdfReconciliation)renderPdfReconciliation(form,app.pdfReconciliation);
}

// Legacy/duplicate PDF imports use the same compact month layout.
const csvPreview=showBankPreview;
showBankPreview=function(p){if(p.already_imported&&p.result?.job_id)return openIntakeJob(p.result.job_id);if(p.resume_job)return openIntakeJob(p.pdf_job_id);if(p.source_kind!=='pdf'||p.already_imported)return csvPreview(p);app.bankPreview=p;const review=p.rows.filter(r=>['manual_review','error'].includes(r.status));showModal(review.length?'Vorhandene Zahlungen abgleichen':'Deine Zahlungen prüfen',`<form id="bank-commit-form" data-id="${p.id}" data-selection-token="${esc(p.pdf_selection_token||'')}" novalidate><div class="modal-body pdf-review-screen"><p class="save-state" role="status">Original und Einordnungen gespeichert. Noch nicht im Dashboard.</p><p class="pdf-review-help">${review.length?'Einige Zahlungen könnten bereits erfasst sein oder brauchen noch eine Korrektur. Prüfe die markierten Zeilen, bevor du die Liste freigibst.':'Prüfe die Einordnung und gib deine Auswahl frei.'}</p><div class="actions">${button('Original öffnen','bank-original','file','small',`data-id="${p.id}" data-filename="${esc(p.filename)}"`)}${button('Zahlungsliste bearbeiten','reopen-pdf-review','','small',`data-id="${p.id}"`)}</div><div id="import-ai-status" class="small muted"></div>${p.errors.length?`<p class="form-error">${p.errors.map(e=>esc(e.message)).join(' · ')}</p>`:''}<div class="review-list">${pdfGroupMarkup(p.rows,(r,i)=>`<article class="review-row pdf-payment" data-line="${r.line}"><div class="pdf-payment-main"><time class="pdf-date">${esc(pdfDate(r.booked_on))}</time><div class="pdf-recipient"><strong>${esc(r.partner)}</strong><p class="pdf-purpose" title="${esc(r.purpose)}">${esc(r.purpose)}</p><span class="small ${['manual_review','error'].includes(r.status)?'error-text':'muted'}">${rowStatus[r.status]}</span></div><strong class="pdf-amount">${money(r.amount_cents)}</strong><div class="pdf-scope-picker"><label><span class="sr-only">Einordnung Zahlung ${i+1}</span><select class="import-scope"${r.classification==='transfer'?' disabled':''}>${options(Object.entries(scopeNames),r.scope)}</select></label></div></div><details class="pdf-duplicate-choice"${r.status!=='ready'?' open':''}><summary>Übernahme ändern / auslassen</summary><p class="small muted">${esc(r.note||'')}</p><label>Was soll mit dieser Zahlung passieren?<select class="import-choice" data-line="${r.line}"${['outside_year','error'].includes(r.status)?' disabled':''}>${options(rowChoices(r),r.choice||(r.status==='ready'?'create':r.status==='manual_review'?'review':'skip'))}</select></label></details><details class="pdf-row-details"><summary>Kategorie & Notiz</summary><label>Kategorie<select class="import-category">${options(categories,r.category||'Unsortiert')}</select></label><label>Deine Notiz<textarea class="import-note" rows="2" maxlength="2000">${esc(r.review_note||'')}</textarea></label></details></article>`)}</div><p class="small muted">Eine Zeile stimmt nicht? Über „Zahlungsliste bearbeiten“ kannst du Gebührenaufschlüsselungen entfernen oder Angaben korrigieren.</p></div><div class="modal-footer pdf-review-footer"><div class="form-result" role="alert" tabindex="-1"></div><label class="check pdf-approval"><input name="checked" type="checkbox">Original, Einordnung und mögliche Doppelungen geprüft.</label><div class="pdf-submit-row"><button class="btn primary" type="submit">Freigeben & im Dashboard anzeigen</button></div></div></form>`);$('#bank-commit-form').querySelectorAll('.review-row').forEach(row=>row.addEventListener('input',()=>queuePreviewEdit(row,p.id)));};
